import{$,db,rpc,run,notice,money,phone,el,renderTransactions,renderMessages}from'./client.js';
let selected=null,creditTarget=null,creditId=null,resetTarget=null,replyId=null,chatMode=false;
async function load(){const rows=await rpc('admin_list');$('adminLogin').hidden=true;$('adminWorkspace').hidden=false;$('adminLogout').hidden=false;$('agents').replaceChildren();if(!rows.length)$('agents').append(el('p','ماكو صيرفات بعد. أضف أول صيرفة من الأعلى.'));for(const a of rows){const box=el('article',null,'record');box.append(el('h3',a.name),el('p',phone(a.phone)+' · '+(a.active?'فعال':'موقوف')),el('strong','الرصيد: '+money(a.balance)));const button=(label,fn)=>{const b=el('button',label,'quiet');b.onclick=()=>run(fn);box.append(b);};button('إضافة رصيد',async()=>{creditTarget=a;creditId=crypto.randomUUID();$('creditName').textContent=a.name+' · الرصيد الحالي: '+money(a.balance);$('creditAmount').value='';$('creditSummary').textContent='';$('creditDialog').showModal();});button('المعاملات',()=>detail(a,false));button('الدعم',()=>detail(a,true));button(a.active?'إيقاف الحساب':'تفعيل الحساب',async()=>{if(!confirm((a.active?'إيقاف':'تفعيل')+' حساب '+a.name+'؟'))return;await rpc('admin_toggle',{agent_id:a.id,active:!a.active});await load();});button('تغيير كلمة السر',async()=>{resetTarget=a;$('resetPin').value='';$('resetDialog').showModal();});$('agents').append(box);}}
$('adminLoginForm').onsubmit=e=>{e.preventDefault();run(async()=>{const{data,error}=await db.functions.invoke('taktooka-admin-login',{body:{phone:$('phone').value.trim(),pin:$('pin').value}});$('pin').value='';if(error||!data?.refresh_token)throw new Error('LOGIN_FAILED');const r=await db.auth.refreshSession({refresh_token:data.refresh_token});if(r.error)throw r.error;await load();notice('تم تسجيل دخول الإدارة.');});};
$('adminLogout').onclick=()=>run(async()=>{await db.auth.signOut();location.reload();});$('refreshAgents').onclick=()=>run(load);
$('createForm').onsubmit=e=>{e.preventDefault();run(async()=>{await rpc('admin_create',{name:$('newName').value,phone:$('newPhone').value,pin:$('newPin').value});$('createForm').reset();await load();notice('تم إنشاء الصيرفة برصيد صفر.');});};
function digits(v){return String(v).replace(/[٠-٩۰-۹]/g,c=>'٠١٢٣٤٥٦٧٨٩'.includes(c)?'٠١٢٣٤٥٦٧٨٩'.indexOf(c):'۰۱۲۳۴۵۶۷۸۹'.indexOf(c)).replace(/[^0-9]/g,'');}
$('creditAmount').oninput=()=>{creditId=crypto.randomUUID();const n=Number(digits($('creditAmount').value));$('creditAmount').value=n?n.toLocaleString('en-US'):'';$('creditSummary').textContent=n?'الرصيد بعد الإضافة: '+money(creditTarget.balance+n):'';};
$('cancelCredit').onclick=()=>$('creditDialog').close();$('creditForm').onsubmit=e=>{e.preventDefault();run(async()=>{const amount=Number(digits($('creditAmount').value));await rpc('admin_credit',{agent_id:creditTarget.id,id:creditId,amount});$('creditDialog').close();await load();notice('تمت إضافة '+money(amount)+' إلى رصيد الصيرفة.');});};
$('cancelReset').onclick=()=>$('resetDialog').close();$('resetForm').onsubmit=e=>{e.preventDefault();run(async()=>{await rpc('admin_reset',{agent_id:resetTarget.id,pin:$('resetPin').value});$('resetPin').value='';$('resetDialog').close();notice('تم تغيير كلمة السر وإنهاء الجلسات القديمة.');});};
async function detail(a,chat){selected=a;chatMode=chat;$('details').hidden=false;$('detailTitle').textContent=a.name;$('chat').hidden=!chat;$('adminTransactions').hidden=chat;if(chat)await messages();else renderTransactions(await rpc('admin_transactions',{agent_id:a.id}),$('adminTransactions'));$('details').scrollIntoView({behavior:'smooth',block:'start'});}
async function messages(){renderMessages(await rpc('admin_messages',{agent_id:selected.id}),$('adminMessages'));}
$('showTransactions').onclick=()=>run(()=>detail(selected,false));$('showMessages').onclick=()=>run(()=>detail(selected,true));$('reply').oninput=()=>replyId=null;$('replyForm').onsubmit=e=>{e.preventDefault();run(async()=>{replyId??=crypto.randomUUID();renderMessages(await rpc('admin_send',{agent_id:selected.id,body:$('reply').value,id:replyId}),$('adminMessages'));$('reply').value='';replyId=null;});};
setInterval(()=>{if(selected&&chatMode&&!document.hidden&&!document.body.dataset.busy)messages().catch(()=>{});},7000);
run(async()=>{const{data}=await db.auth.getSession();if(data.session)await load();});
